import base64, glob, os

MAX_REFS = 3
style_cache = {}
out = []
for it in _items:
    j = it.get('json', {})
    inner = j.get('item')
    shot = inner if isinstance(inner, dict) else j
    slug = shot.get('slug')
    root = '/home/node/files/films/' + slug
    chars = shot.get('character_blocks') or []
    ref_parts = []
    ref_notes = []
    for c in chars:
        if len(ref_parts) >= MAX_REFS:
            break
        p = os.path.join(root, 'refs', 'anchors', 'char_%s.jpg' % c.get('id'))
        if os.path.exists(p):
            with open(p, 'rb') as fh:
                url = 'data:image/jpeg;base64,' + base64.b64encode(fh.read()).decode('ascii')
            ref_parts.append({'type': 'image_url', 'image_url': {'url': url}})
            ref_notes.append(('char', c.get('name') or c.get('id')))
    if not ref_parts:
        if slug not in style_cache:
            style_cache[slug] = sorted(glob.glob(os.path.join(root, 'refs', 'ref_*.jpg')))[:MAX_REFS]
        for p in style_cache[slug]:
            with open(p, 'rb') as fh:
                url = 'data:image/jpeg;base64,' + base64.b64encode(fh.read()).decode('ascii')
            ref_parts.append({'type': 'image_url', 'image_url': {'url': url}})
            ref_notes.append(('style', ''))
    lines = ['Cinematic 16:9 film still, single frame.']
    if shot.get('style_notes'):
        lines.append('Overall style: ' + shot['style_notes'])
    for i, (kind, label) in enumerate(ref_notes, 1):
        if kind == 'style':
            lines.append('IMAGE %d shows the overall look of the film; match its lighting, palette and mood.' % i)
        else:
            lines.append('IMAGE %d is the canonical reference for %s. %s must look EXACTLY like in image %d: identical face, hairstyle, body type and clothing.' % (i, label, label, i))
    for c in chars:
        desc = (c.get('visual_description') or '').strip()
        if desc:
            lines.append('%s character sheet: %s' % (c.get('name') or c.get('id'), desc))
    lines.append('Scene: ' + shot.get('image_prompt', ''))
    lines.append('Photorealistic, cinematic lighting. Every recurring character must stay pixel-consistent with their reference image. No text, captions, watermarks, or borders.')
    body = {'model': shot.get('image_model') or 'google/gemini-3.1-flash-image',
            'prompt': '\n'.join(lines), 'aspect_ratio': '16:9',
            'input_references': ref_parts}
    out.append({'json': {'shotId': shot.get('id'), 'slug': slug, 'body': body, 'ref_count': len(ref_parts)}})
return out

