const srcs = $('Build Image Request').all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const resp = items[i].json ?? {};
  const src = srcs[i] ? srcs[i].json : {};
  const shotId = src.shotId ?? ('unknown_' + i);
  const slug = src.slug;
  const arr = Array.isArray(resp.data) ? resp.data : [];
  const img = arr.find((d) => d && d.b64_json);
  if (!img) {
    const reason = (resp.error && (resp.error.message || resp.error.code))
      || (resp.choices && resp.choices[0] && resp.choices[0].message && resp.choices[0].message.content)
      || 'no image in OpenRouter response';
    throw new Error('Shot ' + shotId + ' failed: ' + String(reason).slice(0, 300));
  }
  out.push({ json: { slug, shotId, imageB64: img.b64_json } });
}
return out;
